private class PigeonStreamHandler<ReturnType>: NSObject, FlutterStreamHandler {
  private let wrapper: PigeonEventChannelWrapper<ReturnType>
  private var pigeonSink: PigeonEventSink<ReturnType>? = nil

  init(wrapper: PigeonEventChannelWrapper<ReturnType>) {
    self.wrapper = wrapper
  }

  func onListen(withArguments arguments: Any?, eventSink events: @escaping FlutterEventSink)
    -> FlutterError?
  {
    pigeonSink = PigeonEventSink<ReturnType>(events)
    wrapper.onListen(withArguments: arguments, sink: pigeonSink!)
    return nil
  }

  func onCancel(withArguments arguments: Any?) -> FlutterError? {
    pigeonSink = nil
    wrapper.onCancel(withArguments: arguments)
    return nil
  }
}

class PigeonEventChannelWrapper<ReturnType> {
  func onListen(withArguments arguments: Any?, sink: PigeonEventSink<ReturnType>) {}
  func onCancel(withArguments arguments: Any?) {}
}

class PigeonEventSink<ReturnType> {
  private let sink: FlutterEventSink

  init(_ sink: @escaping FlutterEventSink) {
    self.sink = sink
  }

  func success(_ value: ReturnType) {
    sink(value)
  }

  func error(code: String, message: String?, details: Any?) {
    sink(FlutterError(code: code, message: message, details: details))
  }

  func endOfStream() {
    sink(FlutterEndOfEventStream)
  }

}

/// A typed channel for communicating with the Flutter application using asynchronous event streams.
class WatchPlatformStateEventChannel {
  private let channel: FlutterEventChannel

  init(messenger: FlutterBinaryMessenger, instanceName: String = "") {
    var channelName = "dev.flutter.pigeon.voice_platform.VoicePlatformEventApi.watchPlatformState"
    if !instanceName.isEmpty {
      channelName += ".\(instanceName)"
    }
    channel = FlutterEventChannel(name: channelName, binaryMessenger: messenger, codec: voicePlatformApiPigeonMethodCodec)
  }

  /// Sets the stream handler for this channel, replacing any previous handler.
  /// 
  /// Pass `nil` to remove the event channel registration.
  func setStreamHandler(_ streamHandler: WatchPlatformStateStreamHandler?) {
    let internalHandler = streamHandler.map({ PigeonStreamHandler<PlatformStateMessage>(wrapper: $0) })
    channel.setStreamHandler(internalHandler)
  }
}

class WatchPlatformStateStreamHandler: PigeonEventChannelWrapper<PlatformStateMessage> {
  /// Creates and returns a new event channel that calls the provided stream handler.
  /// 
  /// The returned channel can be stored to allow changing or removing the stream handler.
  /// If the handler will not be changed for the lifetime of the engine associated with the messenger,
  /// the return value can be ignored.
  @discardableResult static func register(
    with messenger: FlutterBinaryMessenger,
    instanceName: String = "",
    streamHandler: WatchPlatformStateStreamHandler
  ) -> WatchPlatformStateEventChannel {
    let channel = WatchPlatformStateEventChannel(messenger: messenger, instanceName: instanceName)
    channel.setStreamHandler(streamHandler)
    return channel
  }
}
      
